// Multiply by Power of Two (x * 8)
int multiply_pow2(int x) {
    return x << 3; // Equivalent to x * 2^3
}

// Divide by Power of Two (x / 4)
int divide_pow2(unsigned int x) {
    return x >> 2; // Equivalent to x / 2^2
}

// Optimized Multiply by 7 (x * 7)
// Decompose: x * (8 - 1)
int multiply_by_7(int x) {
    return (x << 3) - x;
}

// Optimized Multiply by 15 (x * 15)
// Decompose: x * (16 - 1)
int multiply_by_15(int x) {
    return (x << 4) - x;
}

// Optimized Multiply by 9 (x * 9)
// Decompose: x * (8 + 1)
int multiply_by_9(int x) {
    return (x << 3) + x;
}
